/**
 * kookit.min.js — Kittlibr Hardened Viewport Shim & Renderer Harness
 * Integrates EncodingFallbackSniffer, DefensiveArchiveUnpacker, and StructuralLocationAnchor
 * directly into the file-open and rendering pipeline before dispatching to reader view.
 */

import { EncodingFallbackSniffer } from '../utils/hardening/EncodingFallbackSniffer';
import { DefensiveArchiveUnpacker } from '../utils/hardening/DefensiveArchiveUnpacker';
import { StructuralLocationAnchor, StructuralPosition } from '../utils/hardening/StructuralLocationAnchor';

export interface OpenedChapterPayload {
  id: string;
  title: string;
  href: string;
  html: string;
  index: number;
}

export interface OpenedBookPayload {
  filename: string;
  decodedContent: string;
  detectedEncoding: string;
  isArchive: boolean;
  anchor?: StructuralPosition;
  sanitized: boolean;
  title?: string;
  author?: string;
  canonicalId?: string;
  chapters?: OpenedChapterPayload[];
  isEpub?: boolean;
}

export class HardenedKookitEngine {
  private currentAnchor: StructuralPosition | null = null;

  /**
   * File-open pipeline:
   * 1. Check archive signatures (DefensiveArchiveUnpacker / Zip-Slip sanitization)
   * 2. Detect & decode encoding (EncodingFallbackSniffer - UTF-8, GBK, Shift-JIS, Win-1252)
   * 3. Attach StructuralLocationAnchor for resize/reflow survivability
   */
  public static async openFile(filename: string, rawBuffer: Uint8Array, lastPosition?: StructuralPosition): Promise<OpenedBookPayload> {
    console.log(`[kookit-hardened] Opening file: ${filename} (${rawBuffer.length} bytes)`);

    // Step 1: Defensive archive validation
    const zipCheck = DefensiveArchiveUnpacker.validateZipHeader(rawBuffer);
    let sanitized = true;

    if (zipCheck.isValid) {
      // Validate path traversal protection
      const safePath = DefensiveArchiveUnpacker.sanitizeEntryPath(filename, '/cache');
      if (!safePath) {
        throw new Error(`[SecurityException] Unsafe file path rejected: ${filename}`);
      }

      // Check if it's an EPUB archive
      if (filename.toLowerCase().endsWith('.epub') || zipCheck.isFb2Zip) {
        try {
          const epubData = await DefensiveArchiveUnpacker.unpackEpub(rawBuffer, {
            logDiagnostic: (evt) => {
              console.log(`[${evt.source}][${evt.stage}] ${evt.message}`, evt.meta || '');
            }
          });

          const chapters: OpenedChapterPayload[] = epubData.chapters.map((ch, idx) => ({
            id: ch.id,
            title: ch.title,
            href: ch.href,
            html: ch.html,
            index: idx
          }));

          const primaryContent = chapters.length > 0 ? chapters[0].html : '';
          const anchor = lastPosition || StructuralLocationAnchor.createAnchor(0, 0, 0, chapters.length, primaryContent.slice(0, 80));

          return {
            filename,
            title: epubData.title,
            author: epubData.author,
            canonicalId: epubData.identifier,
            decodedContent: primaryContent,
            detectedEncoding: 'UTF-8',
            isArchive: true,
            isEpub: true,
            chapters,
            anchor,
            sanitized: true
          };
        } catch (err: any) {
          console.error(`[kittlibr-reader][parse] EPUB unpack error for ${filename}:`, err);
          throw err;
        }
      }
    }

    // Step 2: Fallback encoding sniffing to eliminate mojibake
    const sniffResult = EncodingFallbackSniffer.sniffAndDecode(rawBuffer);
    console.log(`[kookit-hardened] Sniffed encoding: ${sniffResult.encoding} (confidence: ${sniffResult.confidence})`);

    // Step 3: Structural Location Anchoring
    let anchor: StructuralPosition;
    if (lastPosition) {
      anchor = lastPosition;
    } else {
      anchor = StructuralLocationAnchor.createAnchor(0, 0, 0, 100, sniffResult.decodedText.slice(0, 80));
    }

    return {
      filename,
      decodedContent: sniffResult.decodedText,
      detectedEncoding: sniffResult.encoding,
      isArchive: zipCheck.isValid,
      anchor,
      sanitized
    };
  }
}

// Global hook for browser / Electron environment
if (typeof window !== 'undefined') {
  (window as any).HardenedKookitEngine = HardenedKookitEngine;
}
